mapper.select:
SELECT count(*)
  FROM resource_node
 WHERE tenant_id = #{param1}
   AND id = #{param2}
   AND kind = 'island'
   AND deleted_at IS NULL

SELECT island_id
  FROM workflow
 WHERE tenant_id = #{param1}
   AND id = #{param2}

SELECT count(*)
  FROM workflow
 WHERE tenant_id = #{param1}
   AND code = #{param2}

SELECT w.id, w.code, w.name, w.category, w.version, w.status, w.island_id AS "islandId", rn.code AS "islandCode", rn.name AS "islandName", w.created_at AS "createdAt", w.updated_at AS "updatedAt", w.updated_by AS "updatedBy", (SELECT count(*) FROM workflow_node n WHERE n.workflow_id = w.id AND n.node_type = 'task') AS task_count FROM workflow w LEFT JOIN resource_node rn ON rn.id = w.island_id AND rn.kind = 'island' WHERE w.tenant_id = #{tenantId} AND w.deleted_at IS NULL
AND w.category = #{category}
AND (w.name ILIKE '%' || #{q} || '%' OR w.code ILIKE '%' || #{q} || '%')
AND w.island_id IS NULL AND w.island_id = #{islandId}::bigint
AND NOT EXISTS (SELECT 1 FROM workflow_node n WHERE n.workflow_id = w.id AND n.node_type = 'task')
ORDER BY w.updated_at DESC NULLS LAST, w.id DESC LIMIT #{limit} OFFSET #{offset}
